#include "net_asset_server.h"
#include <string.h>
int asset_server_handle_get(const asset_server*s,const uint8_t*q,size_t qn,uint8_t*out,size_t cap,size_t*on){asst_header h;const asset_server_entry*e=NULL;size_t i,n;if(!s||!q||!out||!on||qn!=32||asst_decode(&h,q)<0||h.type!=ASST_GET||h.payload_len==0)return -1;for(i=0;i<s->count;i++)if(s->entries[i].id==h.asset_id)e=&s->entries[i];if(!e||h.offset>e->length||h.payload_len>e->length-h.offset)return -2;n=h.payload_len;if(cap<32+n)return -3;h.type=ASST_DATA;h.flags=(h.offset+n==e->length)?ASST_LAST:0;h.payload_crc32=asst_crc32(e->data+h.offset,(uint32_t)n);if(asst_encode(out,&h)<0)return -1;memcpy(out+32,e->data+h.offset,n);*on=32+n;return 0;}
int asset_fetch(asset_io_exchange io,void*ctx,uint32_t session,uint32_t id,size_t total,uint32_t crc,uint8_t*dst,size_t cap,uint32_t timeout,unsigned retries){size_t off=0;uint32_t seq=0;unsigned attempt;uint8_t req[32],resp[1056];size_t rn;asst_header h; if(!io||!dst||total==0||total>cap)return -1;while(off<total){uint16_t ask=(uint16_t)((total-off)>ASST_MAX_PAYLOAD?ASST_MAX_PAYLOAD:(total-off));if(off+ask<total)ask=(uint16_t)(ask&~3u);if(!ask)return -1;h=(asst_header){.magic=ASST_MAGIC,.version=ASST_VERSION,.type=ASST_GET,.session=session,.asset_id=id,.offset=(uint32_t)off,.payload_len=ask,.flags=0,.sequence=seq,.payload_crc32=0};if(asst_encode(req,&h)<0)return -1;int accepted=0;for(attempt=0;attempt<=retries;attempt++){if(attempt)h.flags=ASST_RETRY;asst_encode(req,&h);if(io(ctx,req,32,resp,sizeof resp,&rn,timeout)==0&&rn>=33&&asst_decode(&h,resp)==0&&h.type==ASST_DATA&&h.session==session&&h.asset_id==id&&h.offset==off&&h.sequence==seq&&h.payload_len==ask&&h.payload_crc32==asst_crc32(resp+32,ask)&&h.payload_len<=rn-32){if((h.flags&ASST_LAST)!=(off+ask==total))continue;memcpy(dst+off,resp+32,ask);off+=ask;seq++;accepted=1;break;}}if(!accepted)return -2;}return asst_crc32(dst,(uint32_t)total)==crc?0:-3;}
